{
  "tasks": [
    {
      "task_id": "T1",
      "title": "2026年每月任务数量统计",
      "business_question": "2026年每个月创建的任务数量是多少？按月份升序排列。",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标，缺失将导致无法获取任何有效数据。",
      "requirement_ids": ["C01", "C02", "C03", "C04"],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "year_created"
          }
        },
        {
          "step_id": "S2",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "year_created",
                "operator": "eq",
                "value": 2026
              }
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "month_created"
          }
        },
        {
          "step_id": "S4",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "month_created"
            ]
          }
        },
        {
          "step_id": "S5",
          "operation": "sort",
          "params": {
            "field": "month_created",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
